// Reads both sheets, drops anyone already contacted, and queues the rest.
// Only rows with Status Done/true (an email was actually found) are eligible.
const READY = ['done', 'true'];
const trackingRows = $('Read Tracking').all().map(item => item.json);
const contactedEmails = new Set(trackingRows.map(r => (r['Email Address'] || '').trim().toLowerCase()).filter(Boolean));
const todayStr = new Date().toISOString().slice(0, 10);
const startCountToday = trackingRows.filter(r => (r['Date Sent'] || '').slice(0, 10) === todayStr).length;
const startCountAllTime = trackingRows.filter(r => (r['Email Address'] || '').trim() !== '').length;
const queuedThisRun = new Set();
const output = [];
for (const item of $('Read Prospects').all()) {
  const row = item.json;
  const status = String(row.Status || '').trim().toLowerCase();
  if (READY.indexOf(status) === -1) continue;
  const emailList = String(row.Emails || '').split(/[,;]/).map(e => e.trim()).filter(Boolean);
  for (const email of emailList) {
    const key = email.toLowerCase();
    if (contactedEmails.has(key) || queuedThisRun.has(key)) continue;
    queuedThisRun.add(key);
    output.push({ json: { domain: row.Domain, recipientEmail: email, searchQuery: row.query || '', pageUrl: row.url || '', pageTitle: row.title || '', pageSnippet: (row.snippet || '').slice(0, 300), queuePosition: output.length, startCountToday, startCountAllTime } });
  }
}
return output;

// 2 mailboxes x 20/day each = 40/day shared cap, alternated evenly across the run.
const DAILY_CAP = 40;
const sentSoFarToday = ($json.startCountToday || 0) + ($json.queuePosition || 0);
return [{ json: { ...$json, capReached: sentSoFarToday >= DAILY_CAP, dailyCap: DAILY_CAP } }];

// Decides whether an address is safe to mail. 'catchall' domains accept anything
// (common for blog/agency domains) so they're accepted by default; stricter
// deployments can drop 'catchall' from ACCEPT at the cost of volume.
const ACCEPT = ['valid', 'catchall'];
const PERMANENT = ['invalid', 'disposable'];
const res = $json || {};
const apiOk = res.status === 'success';
const result = apiOk ? String(res.result || 'unknown') : 'api_error';
return [{ json: { ...$('Check Daily Cap').item.json, deliverable: ACCEPT.indexOf(result) !== -1, logSkip: PERMANENT.indexOf(result) !== -1, verifyResult: result } }];

// Alternate mailboxes evenly across the whole history, not just this run.
const useAccountA = ((($json.startCountAllTime || 0) + ($json.queuePosition || 0)) % 2 === 0);
return [{ json: { ...$json, sendAccountLabel: useAccountA ? 'AccountA' : 'AccountB' } }];

// Builds the personalization prompt for the LLM-drafted mailbox, or the fixed
// approved copy for the other mailbox. Only references a scraped article by
// name if the title looks like an actual article, not a nav/category page.
const COMPANY = '{{COMPANY_NAME}}';
function toHost(raw) { let s = String(raw||'').trim(); s = s.split('#')[0].split('?')[0].replace(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//, '').replace(/^[^@\/]*@/, ''); return s.split('/')[0].split(':')[0].toLowerCase().replace(/^www\./, ''); }
function toBrand(host) { if (!host) return 'your'; let labels = host.split('.').filter(Boolean); if (labels.length > 1) labels = labels.slice(0, -1); const label = labels[labels.length-1] || host; return label.split(/[-_]/).filter(Boolean).map(w => w[0].toUpperCase()+w.slice(1)).join(' '); }
function usableTitle(raw) { let t = String(raw||'').trim(); if (!t) return ''; t = t.split(/\s+[|\u2013\u2014-]\s+/)[0].trim(); if (/guest post|write for us|contribute|submit|sponsored/i.test(t)) return ''; if (/^(home|blogs?|news|articles?|resources?|categor|about|contact)\b/i.test(t)) return ''; if (t.split(/\s+/).length < 4) return ''; return t; }
const host = toHost($json.domain);
const siteName = toBrand(host);
const isAccountA = $json.sendAccountLabel === 'AccountA';
const articleTitle = usableTitle($json.pageTitle);
const ANGLES = ['what this actually costs a small team to run', 'why a build pipeline change moves quality metrics', 'the hidden cost of a slow first-week experience', 'what QA looks like shipping weekly on two platforms'];
const angle = ANGLES[$json.queuePosition % ANGLES.length];
const LLM_PROMPT = ['Generate one fresh guest post outreach email, following the system instructions exactly.', 'You are a content marketer at ' + COMPANY + ' asking this blog about contributing a guest article.', 'Vary tone and structure meaningfully each time, never repeat a template.', articleTitle ? ('They published an article titled "' + articleTitle + '" - work one short, specific reference to it into the first paragraph. Do not say you loved it.') : 'No specific article was found - do not pretend to have read anything.'].join('\n');
const FIXED_SUBJECT = 'Guest post for ' + siteName + ' on drop-off data';
const FIXED_BODY = 'Hi ' + siteName + ' team,\n\nMost guest articles on this topic repeat the same generic advice without the underlying math. We ran a data-backed experiment and turned it into an exclusive breakdown for a few select blogs.\n\nWould a short outline be worth sending over?\n\nBest,\n' + COMPANY;
return [{ json: { ...$json, domain: host, siteName, company: COMPANY, useFixedCopy: isAccountA, fixedSubject: isAccountA ? FIXED_SUBJECT : '', fixedBody: isAccountA ? FIXED_BODY : '', aiPrompt: isAccountA ? 'FIXED COPY, sent verbatim' : LLM_PROMPT } }];

// Splits SUBJECT: line off the top, strips placeholder brackets/markdown/smart
// punctuation the model sometimes emits, guarantees a 2-paragraph shape for the
// LLM path (fixed copy is left untouched), and computes compliance stats
// (word/sentence/subject-length counts) so the tracking sheet shows whether
// the model actually stayed inside the prompt's own limits.
const source = $('Build Prompt').item.json;
const raw = source.useFixedCopy ? ('SUBJECT: ' + source.fixedSubject + '\n\n' + source.fixedBody) : ($json.output || '').toString();
// ... cleaning/formatting logic identical in spirit to the real system: strip
// placeholder brackets, normalize smart quotes/dashes, enforce paragraph count,
// then compute wordCount/sentenceCount/subjectLength and an out-of-range flag
// list so a reviewer can see at a glance whether a given send violated the
// prompt's own style contract.
return [{ json: { ...source, emailSubject: 'PLACEHOLDER_SUBJECT', emailBody: 'PLACEHOLDER_BODY', copyStats: 'see production implementation for full compliance-stats logic' } }];
